<?php
defined('ABSPATH')||exit;final class SPL_Interactions{
 public function hooks(){add_action('wp_ajax_spl_action',array($this,'ajax'));}
 public static function controls($id){ob_start();?><section class="spl-controls" data-document="<?php echo absint($id);?>"><?php if(is_user_logged_in()):?><button data-spl="save">Save</button><button data-spl="like">Like</button><button data-spl="dislike">Dislike</button><details><summary>Reading Progress, Bookmark, or Note</summary><form data-spl-form><select name="kind"><option value="progress">Update reading progress</option><option value="bookmark">Add page bookmark</option><option value="note">Add private note</option><option value="report">Report document</option></select><input type="number" name="page" min="1" placeholder="Page number"><textarea name="text" maxlength="1500" placeholder="Private note or report details"></textarea><select name="reason"><option value="copyright">Copyright violation</option><option value="unauthorized-scan">Unauthorized scan</option><option value="attribution">Incorrect attribution</option><option value="patient-privacy">Patient privacy</option><option value="medical-safety">Medical safety</option><option value="misleading-claim">Misleading health claim</option><option value="false-credentials">False credentials</option><option value="broken-pdf">Broken PDF</option><option value="spam">Spam</option><option value="other">Other</option></select><button>Submit</button></form></details><?php else:?><a href="<?php echo esc_url(wp_login_url(get_permalink($id)));?>">Log in to save, bookmark, or make private notes</a><?php endif;?></section><?php return ob_get_clean();}
 public function ajax(){check_ajax_referer('spl_action','nonce');if(!is_user_logged_in())wp_send_json_error(array('message'=>'Log in first.'),401);$id=absint($_POST['document']??0);$kind=sanitize_key(wp_unslash($_POST['kind']??''));if(SPL_Helpers::TYPE!==get_post_type($id)||'publish'!==get_post_status($id))wp_send_json_error();global$wpdb;$u=get_current_user_id();if(in_array($kind,array('save','like','dislike'),true)){$type='save'===$kind?'save':'reaction';$existing=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}spl_user_data WHERE user_id=%d AND document_id=%d AND data_type=%s LIMIT 1",$u,$id,$type));if($existing&&('save'===$kind||$existing->reaction===$kind))$wpdb->delete($wpdb->prefix.'spl_user_data',array('id'=>$existing->id),array('%d'));else{$data=array('user_id'=>$u,'document_id'=>$id,'data_type'=>$type,'page_number'=>0,'note'=>'','reaction'=>'save'===$kind?'':$kind,'progress'=>0,'updated_at'=>current_time('mysql',true));if($existing){$data['id']=$existing->id;}$wpdb->replace($wpdb->prefix.'spl_user_data',$data);}wp_send_json_success(array('reload'=>true));}$page=max(0,absint($_POST['page']??0));$text=sanitize_textarea_field(wp_unslash($_POST['text']??''));if(in_array($kind,array('progress','bookmark','note'),true)){$wpdb->insert($wpdb->prefix.'spl_user_data',array('user_id'=>$u,'document_id'=>$id,'data_type'=>$kind,'page_number'=>$page,'note'=>$text,'reaction'=>'','progress'=>'progress'===$kind?$page:0,'updated_at'=>current_time('mysql',true)));wp_send_json_success(array('message'=>'Saved privately.'));}if('report'===$kind){$reason=sanitize_key(wp_unslash($_POST['reason']??''));if(!$text)wp_send_json_error(array('message'=>'Report details are required.'));$wpdb->insert($wpdb->prefix.'spl_reports',array('user_id'=>$u,'document_id'=>$id,'reason'=>$reason,'details'=>$text,'status'=>'open','created_at'=>current_time('mysql',true)));wp_send_json_success(array('message'=>'Report received.'));}wp_send_json_error();}
}

